	// Actually x1 can go up to m*b since y1 >= 0 means b - x1/m >= 0, so x1 <= m*b.
	// m <= 1000, b <= 10000, so m*b <= 10^7. That's fine to iterate.

	maxBananas := int64(0)
	for x1 := 0; x1 <= m*b; x1++ {
		// y1 = floor(b - x1/m) = floor((b*m - x1)/m)
		// b - x1/m = (b*m - x1)/m
		// Since x1 and m are integers, b*m - x1 is integer.
		// floor((b*m - x1)/m) = (b*m - x1) / m using integer division (when b*m - x1 >= 0)
		// But we need to be careful with negative values.
		// If b*m - x1 < 0, then y1 < 0, which is invalid.
		numerator := b*m - x1
		if numerator < 0 {
			break
		}
		y1 := numerator / m // integer division, floor for non-negative
		if y1 < 0 {
			break
		}
		// Calculate bananas: (x1+1)*(y1+1)*(x1+y1)/2
		// Use int64 to avoid overflow
		a := int64(x1 + 1)
		c := int64(y1 + 1)
		d := int64(x1 + y1)
		// (a * c * d) / 2
		// One of a, c, d is even, so we can divide by 2 first to avoid overflow
		var product int64
		if a%2 == 0 {
			product = (a / 2) * c * d
		} else if c%2 == 0 {
			product = a * (c / 2) * d
		} else {
			product = a * c * (d / 2)
		}
		if product > maxBananas {
			maxBananas = product
		}
	}

	fmt.Println(maxBananas)
}
