	// We need to find a rectangle [0, x] x [0, y] such that all points (i, j) in the rectangle
	// satisfy i + m*j <= b (on or under the line)
	// The rectangle must have all its points on or under the line.
	// Since the rectangle is axis-aligned with bottom-left at origin (implied by "on or under the line" and the nature of the problem),
	// the top-right corner (x, y) must satisfy x + m*y <= b, and all points in [0,x]x[0,y] must also satisfy this.
	// Actually, the constraint is that the rectangle must be entirely on or under the line.
	// The most restrictive point in the rectangle [0, x] x [0, y] is (x, y) itself.
	// So we need x + m*y <= b.
	// The total bananas in the rectangle is sum_{i=0}^{x} sum_{j=0}^{y} (i + j)
	// = sum_{i=0}^{x} (y+1)*i + sum_{j=0}^{y} (x+1)*j
	// = (y+1) * x*(x+1)/2 + (x+1) * y*(y+1)/2
	// = (x+1)(y+1)(x+y)/2

	var maxBananas int64 = 0

	// y can range from 0 to b/m (since x >= 0, m*y <= b)
	maxY := b / m
	for y := 0; y <= maxY; y++ {
		// x can range from 0 to b - m*y
		maxX := b - m*y
		// We want to maximize (x+1)(y+1)(x+y)/2 over x in [0, maxX]
		// Let f(x) = (x+1)(y+1)(x+y)/2
		// This is a quadratic in x: f(x) = (y+1)/2 * (x^2 + (2y+1)x)
		// Since y >= 0, this is an increasing function of x for x >= 0.
		// So the maximum is at x = maxX.
		x := int64(maxX)
		yi := int64(y)
		bananas := (x + 1) * (yi + 1) * (x + yi) / 2
		if bananas > maxBananas {
			maxBananas = bananas
		}
	}

	fmt.Println(maxBananas)
}

func splitString(s string) []string {
	var result []string
	var current string
	for _, c := range s {
		if c == ' ' {
			if current != "" {
				result = append(result, current)
				current = ""
			}
		} else {
			current += string(c)
		}
	}
	if current != "" {
		result = append(result, current)
	}
	return result
}
