func lineToStrings(line []byte) []string {
	var parts []string
	for _, c := range line {
		if c == ' ' {
			parts = append(parts, "")
		} else {
			if len(parts) == 0 {
				parts = append(parts, string(c))
			} else {
				parts[len(parts)-1] += string(c)
			}
		}
	}
